<?php
require_once 'includes/auth.php';
require_once 'includes/functions.php';
requireLogin();
$pdo=getDBConnection(); $uid=(int)$_SESSION['user_id'];
$search=trim((string)($_GET['q']??'')); $params=[$uid];
$sql="SELECT lk.id,lk.license_key,lk.duration,lk.duration_type,lk.max_devices,lk.price,lk.sold_at,lk.device_id,m.name AS mod_name FROM license_keys lk LEFT JOIN mods m ON m.id=lk.mod_id WHERE lk.sold_to=?";
if($search!==''){$sql.=" AND (lk.license_key LIKE ? OR m.name LIKE ?)";$params[]='%'.$search.'%';$params[]='%'.$search.'%';}
$sql.=" ORDER BY lk.id DESC LIMIT 500";
$stmt=$pdo->prepare($sql);$stmt->execute($params);$keys=$stmt->fetchAll(PDO::FETCH_ASSOC);
$active=0;$expired=0;$all=[];
foreach($keys as &$k){$unit=strtolower((string)$k['duration_type']);try{$expiry=(new DateTimeImmutable((string)$k['sold_at']))->modify('+'.(int)$k['duration'].' '.$unit);$k['expires_at']=$expiry?$expiry->format('d M Y, h:i A'):'—';$k['is_expired']=$expiry && new DateTimeImmutable('now')>$expiry;}catch(Throwable $e){$k['expires_at']='—';$k['is_expired']=false;}if($k['is_expired'])$expired++;else $active++;$all[]=$k['license_key'];}
unset($k);
$page_title='My Keys - '.SITE_NAME;
require_once 'includes/header.php';
?>
