<section class="aw-panel"><div class="flex flex-wrap justify-between items-center gap-3 mb-5"><div><h2 class="font-black text-lg">Key collection</h2><p class="text-xs text-brand-muted mt-1">Showing latest <?=count($keys)?> keys (maximum 500)</p></div><form method="GET"><input class="aw-search" type="search" name="q" value="<?=htmlspecialchars($search)?>" placeholder="Search key or game..."></form></div>
<div class="overflow-x-auto"><table class="aw-table"><thead><tr><th>Game</th><th>License key</th><th>Duration</th><th>Expiry</th><th>Device</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach($keys as $k): ?><tr><td class="font-bold"><?=htmlspecialchars($k['mod_name']??'Unknown')?></td><td><code class="font-mono text-[11px] break-all"><?=htmlspecialchars($k['license_key'])?></code></td><td><?=htmlspecialchars($k['duration'].' '.$k['duration_type'])?></td><td class="text-brand-muted"><?=htmlspecialchars($k['expires_at'])?></td><td class="font-mono text-brand-muted"><?=htmlspecialchars($k['device_id']?:'Not bound')?></td><td><?php if($k['is_expired']): ?><span class="rounded-full bg-rose-500/10 text-rose-400 px-2.5 py-1 text-[10px] font-extrabold">Expired</span><?php else: ?><span class="rounded-full bg-emerald-500/10 text-emerald-400 px-2.5 py-1 text-[10px] font-extrabold">Active</span><?php endif; ?></td><td><button type="button" class="aw-copy" data-key="<?=htmlspecialchars($k['license_key'],ENT_QUOTES)?>" onclick="copyOne(this)">Copy</button></td></tr><?php endforeach; ?>
<?php if(!$keys): ?><tr><td colspan="7" class="text-center py-12 text-brand-muted">No keys found. Generate your first batch to see it here.</td></tr><?php endif; ?>
</tbody></table></div><textarea id="allKeysText" class="sr-only" aria-hidden="true"><?=htmlspecialchars(implode("\n",$all))?></textarea></section>
<script>
async function safeCopy(value){try{await navigator.clipboard.writeText(value);return true}catch(e){const t=document.createElement('textarea');t.value=value;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();const ok=document.execCommand('copy');t.remove();return ok}}
async function copyOne(btn){const ok=await safeCopy(btn.dataset.key);const old=btn.textContent;btn.textContent=ok?'Copied':'Failed';setTimeout(()=>btn.textContent=old,1400)}
async function copyAllKeys(){const t=document.getElementById('allKeysText').value;if(!t){alert('No keys to copy');return}const ok=await safeCopy(t);alert(ok?'All keys copied!':'Copy failed. Please select and copy manually.')}
</script>
